export function shopRows(s,{E,esc},query='',floor='all',availability='ready'){
 const normalize=v=>String(v).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const all=[...new Set(E.mallOf(s).sections.flatMap(d=>d.stores))].map(E.storeById).filter(Boolean);
 const rows=all.filter(st=>(floor==='all'||E.storeFloor(E.mallOf(s),st.id)===Number(floor))&&(availability==='all'||st.count||E.isServiceStore(st))&&normalize(st.name+' '+st.range).includes(normalize(query))).sort((a,b)=>(E.storeFloor(E.mallOf(s),a.id)!==(s.floor||0))-(E.storeFloor(E.mallOf(s),b.id)!==(s.floor||0))||a.name.localeCompare(b.name));
 return `<p class="shop-results-count" role="status">${rows.length} matching shops · ${availability==='ready'?'Stocked collections & services':'All locations'}</p>${rows.map(st=>`<button class="shop-destination" data-action="visit" data-id="${st.id}"><span class="shop-monogram" style="--shop:${st.color}">${esc(st.name.slice(0,2))}</span><span><strong>${esc(st.name)}</strong><small>${esc(E.planFor(s).levels[E.storeFloor(E.mallOf(s),st.id)])} · ${st.count?st.count+' real products':E.isServiceStore(st)?'Bookable services':'Explore only · collection in research'}</small><b>Walk here & enter →</b></span></button>`).join('')||'<p>No shops match. Try another name or floor.</p>'}`;
}
export function shoppingGuide(s,id,{E,esc},count=0){
 const st=id&&E.storeById(id);
 return st?`<div class="eyebrow">YOU ARE INSIDE</div><h2>${esc(st.name)}</h2><p>${E.isServiceStore(st)?'Browse services, choose a booking and use it here.':'Browse a real product, select a size, then review your bag before paying.'}</p><ol class="shopping-steps"><li><b>1</b><span>Browse & inspect<small>Read a label or choose a product.</small></span></li><li><b>2</b><span>Choose your size<small>Try eligible clothes before buying.</small></span></li><li><b>3</b><span>Review & pay<small>Only checkout spends game money.</small></span></li></ol><button class="button orange wide" data-action="interior-browse">${E.isServiceStore(st)?'View services':'Browse this shop'}</button><button class="button secondary wide" data-action="play-bag">Review bag${count?' · '+count+' items':''}</button><button class="button secondary wide" data-action="leave-shop">Exit ${esc(st.name)} → Mall</button>`:`<div class="eyebrow">YOUR SHOPPING DAY</div><h2>Where shall we go?</h2><p>Choose a stocked shop and we’ll walk to its entrance. Inside, browse, choose a size and check out when you’re ready.</p><button class="button orange wide" data-action="map-panel" data-id="shops">Find a shop</button><button class="button secondary wide" data-action="center-map">Open the center map</button><div class="play-detours"><button data-action="map-panel" data-id="services">Rest, food & friends</button><button data-action="view" data-id="journal">Stories & shared afternoons</button><button data-action="view" data-id="wardrobe">My purchases & outfits</button><button data-action="end-day">Go home & sleep</button></div>`;
}
export function campusMapSVG(layout,position,floor,{E,esc}){
 const c=layout.campus;
 const paths=c.halls.map(e=>{const a=c.nodes[Number(e.a)],b=c.nodes[Number(e.b)];return `<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#fff9eb" stroke-width="${e.width}" stroke-linecap="round"/>`;}).join('');
 const blocks=[...layout.units,...layout.rects,...layout.anchors].map(r=>{const st=E.storeById(r.id),shape=`<rect x="${r.x}" y="${r.y}" width="${r.width}" height="${r.height}" rx="5" fill="${st?.count?'#9a684c':st&&E.isServiceStore(st)?'#698879':'#b7bcaa'}"/>`;return st?`<a href="#shop" data-action="center-unit" data-id="${r.id}" aria-label="Walk to ${esc(st.name)} and enter"><title>${esc(st.name)} · ${st.count?st.count+' products':E.isServiceStore(st)?'Services':'Collection in research'}</title>${shape}</a>`:shape;}).join('');
 const nodes=c.nodes.map(n=>`<a href="#court" data-action="center-zone" data-floor="${floor}" data-id="${n.id}" aria-label="Walk to ${esc(n.label)}"><circle cx="${n.x}" cy="${n.y}" r="32" fill="#496e58"/><text x="${n.x}" y="${n.y-50}" text-anchor="middle" font-size="32" fill="#294d40">${esc(n.label)}</text></a>`).join('');
 const connectors=layout.escalators.map(e=>`<g><rect x="${e.landing.x-25}" y="${e.landing.y-25}" width="50" height="50" rx="9" fill="#4e6580"/><text x="${e.landing.x}" y="${e.landing.y+12}" text-anchor="middle" font-size="34" fill="white">↕</text></g>`).join('');
 const marker=position?`<g><circle cx="${position.x}" cy="${position.y}" r="30" fill="#9c4629" stroke="white" stroke-width="10"/><text x="${position.x}" y="${position.y+75}" text-anchor="middle" font-size="36" font-weight="bold" fill="#593821">YOU</text></g>`:'';
 return `<svg class="campus-plan" viewBox="0 0 ${c.width} ${c.height}" role="group" aria-label="Interactive center map: choose a storefront or court"><rect width="100%" height="100%" rx="50" fill="#d4dece"/>${paths}${blocks}${nodes}${connectors}${marker}</svg>`;
}
